import os


class KPIListener(object):
    ROBOT_LIBRARY_SCOPE = 'GLOBAL'
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self, path):
        self.ROBOT_LIBRARY_LISTENER = self
        self.infolog = open(os.path.join(path, "infolog.txt"), 'a')
        self.console_path = os.path.join(path, "console.txt")
        self.console = open(self.console_path, 'a')
        self.messages = open(os.path.join(path, "messages.txt"), 'a')

    def log_message(self, msg):
        if msg["level"] != "DEBUG" and msg["level"] != "TRACE":
            if "\r" in msg["message"]:
                with open(self.console_path, "a") as file:
                    file.write(msg["message"].strip() + "\n")
            self.infolog.write(str(msg) + msg["message"][0] + "\n")
        if "Unexpected error occurred" in msg["message"] or "Traceback" in msg["message"]:
            with open(self.console_path, "a") as file:
                file.write(msg["message"].strip() + "\n")

    def message(self, msg):
        self.messages.write(str(msg) + "\n")

    def close(self):
        self.infolog.close()
        self.console.close()
        self.messages.close()
